#!/usr/bin/env python3
from pathlib import Path

SRC=Path('market-navigator-turn22-pre-ship.html')
OUT=Path('market-navigator-turn24-pre-ship.html')
s=SRC.read_text()

def one(old,new,label):
    global s
    n=s.count(old)
    if n!=1: raise SystemExit(f'{label}: expected 1 anchor, found {n}')
    s=s.replace(old,new,1)

def allr(old,new,label,min_count=1):
    global s
    n=s.count(old)
    if n<min_count: raise SystemExit(f'{label}: expected >= {min_count}, found {n}')
    s=s.replace(old,new)

# Identity. The application source remains a clean derivative of exact Turn 22.
one('<title>Market Navigator · Turn 22</title>','<title>Market Navigator · Turn 24</title>','title')
allr('TURN 22 PRE-SHIP','TURN 24 PRE-SHIP','build label')
allr('Market Navigator · Turn 22','Market Navigator · Turn 24','about label')

