old_render="function renderAIConfig(){let r=aiRegistry(),ps=r.providers||{};$('defaultProvider').value=r.defaultProvider||'venice';for(let p of ['venice','openrouter','anthropic']){let q=ps[p]||{};$(p+'Key').value=q.key||'';if(p==='anthropic')$('anthropicModel').value=q.model||'';else fillModelSelect(p+'Model',q.models||([q.model].filter(Boolean)),q.model);setPStatus(p,q.verified?`registered · ${q.model}`:(q.key?'saved · validation required':'not registered'),q.verified?true:null)}$('cfgSummary').textContent=`Default: ${providerName($('defaultProvider').value)}. Keys stay in this browser's local storage.`}"
new_render="""function providerKeyForAction24(p){let q=providerRec(p),el=$(p+'Key'),btn=document.querySelector('[data-replace-key="'+p+'"]');return btn?.dataset.active==='true'?(el?.value.trim()||''):(q.key||el?.value.trim()||'')}function toggleProviderKey24(p){let el=$(p+'Key'),btn=document.querySelector('[data-replace-key="'+p+'"]'),q=providerRec(p);if(!el||!btn)return;let active=btn.dataset.active==='true';if(active){el.value='';btn.dataset.active='false';btn.textContent='Replace key';el.classList.toggle('hidden',!!q.key);setPStatus(p,q.verified?`registered · ${q.model}`:(q.key?'saved · validation required':'not registered'),q.verified?true:null);return}el.value='';el.classList.remove('hidden');btn.classList.remove('hidden');btn.dataset.active='true';btn.textContent='Cancel';setPStatus(p,'replacement draft · validate to save',null);el.focus()}function renderAIConfig(){let r=aiRegistry(),ps=r.providers||{};$('defaultProvider').value=r.defaultProvider||'venice';for(let p of ['venice','openrouter','anthropic']){let q=ps[p]||{},el=$(p+'Key'),btn=document.querySelector('[data-replace-key="'+p+'"]');el.value='';el.classList.toggle('hidden',!!q.key);if(btn){btn.classList.toggle('hidden',!q.key);btn.dataset.active='false';btn.textContent='Replace key'}if(p==='anthropic')$('anthropicModel').value=q.model||'';else fillModelSelect(p+'Model',q.models||([q.model].filter(Boolean)),q.model);setPStatus(p,q.verified?`registered · ${q.model}`:(q.key?'saved · validation required':'not registered'),q.verified?true:null)}$('cfgSummary').textContent=`Default: ${providerName($('defaultProvider').value)}. Registered keys remain in browser storage and are exposed only through explicit replacement.`}"""
