old_load="async function loadProviderModels(p){let key=$(p+'Key').value.trim();if(!key){setPStatus(p,'enter key first',false);return}setPStatus(p,'loading models…');try{let ep=providerEndpoints(p),r=await fetch(ep.models,{cache:'no-store',headers:{Authorization:`Bearer ${key}`}}),x=await r.json();if(!r.ok)throw Error(x.error?.message||`HTTP ${r.status}`);let ids=(x.data||x.models||[]).map(m=>typeof m==='string'?m:(m.id||m.model)).filter(Boolean).sort();if(!ids.length)throw Error('no models returned');fillModelSelect(p+'Model',ids,providerRec(p).model);let reg=aiRegistry(),providers=reg.providers||{};providers[p]={...(providers[p]||{}),key,models:ids,verified:false};saveAIRegistry({...reg,providers});setPStatus(p,`${ids.length} models loaded · choose one`,null)}catch(e){setPStatus(p,e.message,false)}}"
new_load="""async function loadProviderModels(p){let key=providerKeyForAction24(p);if(!key){setPStatus(p,'enter key first',false);return}setPStatus(p,'loading models…');try{let ep=providerEndpoints(p),r=await fetch(ep.models,{cache:'no-store',headers:{Authorization:`Bearer ${key}`}}),x=await r.json();if(!r.ok)throw Error(x.error?.message||`HTTP ${r.status}`);let ids=(x.data||x.models||[]).map(m=>typeof m==='string'?m:(m.id||m.model)).filter(Boolean).sort();if(!ids.length)throw Error('no models returned');fillModelSelect(p+'Model',ids,providerRec(p).model);let reg=aiRegistry(),providers=reg.providers||{},prev=providers[p]||{};providers[p]={...prev,models:ids};saveAIRegistry({...reg,providers});setPStatus(p,`${ids.length} models loaded · choose one`,null)}catch(e){setPStatus(p,e.message,false)}}"""
