old_validate="async function validateProvider(p){let key=$(p+'Key').value.trim(),model=p==='anthropic'?$('anthropicModel').value.trim():$(p+'Model').value;if(!key){setPStatus(p,'enter key first',false);return}if(!model){setPStatus(p,p==='anthropic'?'enter model first':'load models and choose one first',false);return}setPStatus(p,`validating ${model}…`);try{let ep=providerEndpoints(p),headers={'Content-Type':'application/json'},body;if(p==='anthropic'){headers['x-api-key']=key;headers['anthropic-version']='2023-06-01';body={model,max_tokens:8,messages:[{role:'user',content:'Reply OK'}]}}else{headers.Authorization=`Bearer ${key}`;body={model,messages:[{role:'user',content:'Reply OK'}],max_tokens:8}}let r=await fetch(ep.chat,{method:'POST',headers,body:JSON.stringify(body)}),x=await r.json();if(!r.ok)throw Error(x.error?.message||`HTTP ${r.status}`);let reg=aiRegistry(),providers=reg.providers||{},prev=providers[p]||{};providers[p]={...prev,key,model,verified:true,verifiedAt:new Date().toISOString()};reg={...reg,providers,defaultProvider:reg.defaultProvider||p};saveAIRegistry(reg);setPStatus(p,`registered · ${model}`,true);renderAIConfig()}catch(e){let reg=aiRegistry(),providers=reg.providers||{};providers[p]={...(providers[p]||{}),key,model,verified:false};saveAIRegistry({...reg,providers});setPStatus(p,e.message,false)}}"
new_validate="""async function validateProvider(p){let key=providerKeyForAction24(p),model=p==='anthropic'?$('anthropicModel').value.trim():$(p+'Model').value;if(!key){setPStatus(p,'enter key first',false);return}if(!model){setPStatus(p,p==='anthropic'?'enter model first':'load models and choose one first',false);return}setPStatus(p,`validating ${model}…`);try{let ep=providerEndpoints(p),headers={'Content-Type':'application/json'},body;if(p==='anthropic'){headers['x-api-key']=key;headers['anthropic-version']='2023-06-01';body={model,max_tokens:8,messages:[{role:'user',content:'Reply OK'}]}}else{headers.Authorization=`Bearer ${key}`;body={model,messages:[{role:'user',content:'Reply OK'}],max_tokens:8}}let r=await fetch(ep.chat,{method:'POST',headers,body:JSON.stringify(body)}),x=await r.json();if(!r.ok)throw Error(x.error?.message||`HTTP ${r.status}`);let reg=aiRegistry(),providers=reg.providers||{},prev=providers[p]||{};providers[p]={...prev,key,model,verified:true,verifiedAt:new Date().toISOString()};reg={...reg,providers,defaultProvider:reg.defaultProvider||p};saveAIRegistry(reg);renderAIConfig();setPStatus(p,`registered · ${model}`,true)}catch(e){setPStatus(p,e.message,false)}}"""
