# Sources runtime. Registration is an authenticated GitHub issue handoff consumed by the canonical pipeline.
source_runtime=r'''const SOURCE_REGISTRY_PATH24='data/market-backend/source-registry.json';function sourceClassName24(v){return v==='index'?'Market index':v==='equity'?'Equity':v==='etf'?'ETF':v==='fund_cit'?'Fund / CIT / NAV':v||'—'}function sourceIssueUrl24(q,cls){let title='[Market Navigator Source] '+q,body='Query: '+q+'\nClass: '+cls+'\n';return'https://github.com/acmeproducts/stuff/issues/new?'+new URLSearchParams({title,body}).toString()}async function renderSourcesConfig24(){let status=$('sourceStatus'),list=$('sourceList');if(!status||!list)return;status.textContent='Refreshing canonical source registry…';try{let cb='?cb='+Date.now(),[registry,catalog,healthEnvelope]=await Promise.all([j(SOURCE_REGISTRY_PATH24+cb),j('data/market-backend/data-catalog.json'+cb),j('market-evidence/health-envelope.json'+cb)]);S.catalog=catalog;S.catMap=Object.fromEntries((catalog.series||[]).map(x=>[x.id,x]));S.health=healthEnvelope;let regs=registry.registrations||[];list.innerHTML=regs.length?regs.map(r=>{let c=S.catMap[r.id]||{},h=healthEnvelope.series?.[r.id]||{},state=h.classification||r.status||'pending',good=['current','healthy'].includes(state),bad=['failed','missing','unresolved'].includes(state),providers=(r.providerChain||c.provider_chain||[]).map(x=>x.provider).join(' → '),horizons=c.supported_horizons||r.supportedHorizons||[];return`<div class="sourceRow" data-source-id="${esc(r.id)}"><div><strong>${esc(r.canonicalSymbol||r.query)} · ${esc(r.canonicalName||'')}</strong><small>${esc(sourceClassName24(r.instrumentClass))} · ${esc(r.measure||c.canonical_measure||'')} · ${esc(providers||'provider pending')}</small><small>${esc(c.native_cadence||'cadence pending')} · ${esc(horizons.join(' · ')||'horizons pending')}</small></div><span class="sourceState ${good?'good':bad?'bad':''}">${esc(state)}</span></div>`}).join(''):'<div class="sourceRow"><div><strong>No user-registered sources yet.</strong><small>Requests become available only after canonical collection and Health succeed.</small></div></div>';status.textContent='Canonical registry refreshed. Pending/unresolved requests are not treated as chart evidence.';renderHealth()}catch(e){status.textContent='Source registry unavailable: '+e.message;list.innerHTML=''}}$('sourceRegister').onclick=()=>{let q=$('sourceQuery').value.trim(),cls=$('sourceClass').value,status=$('sourceStatus');if(!q){status.textContent='Enter a ticker or instrument name.';return}if(!cls){status.textContent='Choose the intended instrument class. This prevents silent symbol/proxy substitution.';return}status.textContent='Opening the governed registration request. Submit it on GitHub; Refresh after collection completes.';window.open(sourceIssueUrl24(q,cls),'_blank','noopener')};$('sourceRefresh').onclick=()=>renderSourcesConfig24();'''
